TERMINAL_HTML = """<!doctype html><title>GPU Lab Terminal</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;background:#090d12;color:#d5f5d8;font:14px ui-monospace,Consolas,monospace}header{padding:14px 20px;background:#101922;border-bottom:1px solid #254039}main{padding:18px;max-width:1300px;margin:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:800px){.grid{grid-template-columns:1fr}}section{border:1px solid #254039;background:#0c1519}h2{font:13px system-ui;margin:0;padding:10px 12px;background:#12231e;color:#a9e5b0}pre{margin:0;padding:12px;white-space:pre-wrap;max-height:62vh;overflow:auto;color:#d5f5d8}.muted{color:#8ca49a}</style><header><b>GPU Lab · Live terminal</b> <span class="muted">sanitized activity + local job output · refreshes every 2s</span></header><main><div class="grid"><section><h2>Commands</h2><pre id=activity>Connecting…</pre></section><section><h2>Local jobs</h2><pre id=jobs>Connecting…</pre></section></div></main><script>const pretty=x=>JSON.stringify(x,null,2);async function pull(){for(const [u,id] of [['/terminal/activity','activity'],['/terminal/jobs','jobs']])try{document.getElementById(id).textContent=pretty(await (await fetch(u)).json())}catch(e){document.getElementById(id).textContent=e}}pull();setInterval(pull,2000)</script>"""
